CREATE TABLE "User" (id TEXT PRIMARY KEY,email TEXT NOT NULL,passwordHash TEXT NOT NULL,nome TEXT NOT NULL DEFAULT '',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "privacyAcceptedAt" TEXT);
CREATE TABLE "Capitolo" (id TEXT PRIMARY KEY,userId TEXT NOT NULL,titolo TEXT NOT NULL DEFAULT '',genere TEXT NOT NULL DEFAULT 'Autobiografia',testo TEXT NOT NULL DEFAULT '',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Ordine" (id TEXT PRIMARY KEY,userId TEXT NOT NULL,formula TEXT NOT NULL,prezzo INTEGER NOT NULL,stato TEXT NOT NULL DEFAULT 'richiesta',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "projectId" TEXT, "termsAcceptedAt" TEXT);
CREATE TABLE "AiUsage" (userId TEXT NOT NULL,date TEXT NOT NULL,requests INTEGER NOT NULL DEFAULT 0,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(userId,date));
CREATE TABLE "ContactMessage" (id TEXT PRIMARY KEY,fullName TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,lang TEXT NOT NULL,ipHash TEXT NOT NULL,deliveryStatus TEXT NOT NULL DEFAULT 'pending',deliveryError TEXT NOT NULL DEFAULT '',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Session" (id TEXT PRIMARY KEY,userId TEXT NOT NULL,tokenHash TEXT NOT NULL UNIQUE,expiresAt TEXT NOT NULL,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PasswordReset" (id TEXT PRIMARY KEY,userId TEXT NOT NULL,tokenHash TEXT NOT NULL UNIQUE,expiresAt TEXT NOT NULL,usedAt TEXT,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProjectAdmin" (userId TEXT PRIMARY KEY,statoEditoriale TEXT NOT NULL DEFAULT 'iniziato',statoCommerciale TEXT NOT NULL DEFAULT 'gratuito',tutor TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BookProject" (id TEXT PRIMARY KEY,userId TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',genre TEXT NOT NULL DEFAULT 'Autobiografia',tone TEXT NOT NULL DEFAULT 'Emozionante e autentico',audience TEXT NOT NULL DEFAULT 'Famiglia e amici',targetPages INTEGER NOT NULL DEFAULT 80,story TEXT NOT NULL DEFAULT '',people TEXT NOT NULL DEFAULT '',events TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'bozza',plan TEXT NOT NULL DEFAULT 'free',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, "specialDataConsentAt" TEXT);
CREATE TABLE "BookChapter" (id TEXT PRIMARY KEY,projectId TEXT NOT NULL,position INTEGER NOT NULL,title TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'da_generare',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(projectId,position));
CREATE TABLE "BookInterview" (projectId TEXT PRIMARY KEY,questions TEXT NOT NULL DEFAULT '',answers TEXT NOT NULL DEFAULT '',updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuthThrottle" (key TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,windowStart TEXT NOT NULL,blockedUntil TEXT,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BookProjectAdmin" (projectId TEXT PRIMARY KEY,userId TEXT NOT NULL,statoEditoriale TEXT NOT NULL DEFAULT 'iniziato',statoCommerciale TEXT NOT NULL DEFAULT 'gratuito',tutor TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
